def norm(sh):
    rs=[r for r,_ in sh['cells']]; cs=[c for _,c in sh['cells']]
    r0,c0=min(rs),min(cs)
    h=max(rs)-r0+1; w=max(cs)-c0+1
    return {'c':sh['c'],'h':h,'w':w,'n':len(sh['cells']),
            'grid':[[sh['c'] if (r+r0,c+c0) in sh['cells'] else 0 for c in range(w)] for r in range(h)]}

def transform(g):
    H=len(g); W=len(g[0])
    shs=[norm(s) for s in shapes(g)]
    # group by color
    from collections import defaultdict
    byc=defaultdict(list)
    for s in shs: byc[s['c']].append(s)
    colors=list(byc)
    # left color = color owning globally smallest shape (tie: first found)
    smallest=min(shs,key=lambda s:s['n'])
    leftc=smallest['c']; rightc=[c for c in colors if c!=leftc][0]
    L=sorted(byc[leftc],key=lambda s:s['n'])
    R=sorted(byc[rightc],key=lambda s:s['n'])
    pairs=list(zip(L,R))
    out=[[0]*W for _ in range(H)]
    # blocks bottom-anchored, 1 blank row between; bottom of last block = H-1
    bottom=H-1
    rcol=max(s['w'] for s in L)+1
    for lp,rp in reversed(pairs):
        bh=max(lp['h'],rp['h'])
        b0=bottom-bh+1
        for r in range(lp['h']):
            for c in range(lp['w']):
                if lp['grid'][r][c]: out[b0+ (bh-lp['h']) + r][c]=lp['grid'][r][c]
        for r in range(rp['h']):
            for c in range(rp['w']):
                if rp['grid'][r][c]: out[b0+(bh-rp['h'])+r][rcol+c]=rp['grid'][r][c]
        bottom=b0-2
    return out

